 * world.ts — the physics world: gravity, broadphase-free narrowphase over all
 * pairs, velocity solving, positional correction, integration.
 */

import { Body, v2, type Vec2 } from './body';
import { collide, correctPositions, solveContacts, type Contact } from './solver';

export interface WorldOptions {
  gravity?: Vec2;
  /** Solver iterations per step. */
  iterations?: number;
  /** Baumgarte correction percent. */
  correctionPercent?: number;
  /** Allowed penetration before correction kicks in. */
  correctionSlop?: number;
}

export class World {
  gravity: Vec2;
  readonly bodies: Body[] = [];
  readonly iterations: number;
  readonly correctionPercent: number;
  readonly correctionSlop: number;
  /** Contacts generated during the most recent step. */
  lastContacts: Contact[] = [];

  constructor(opts: WorldOptions = {}) {
    this.gravity = opts.gravity ? { ...opts.gravity } : v2(0, -9.81);
    this.iterations = opts.iterations ?? 8;
    this.correctionPercent = opts.correctionPercent ?? 0.8;
    this.correctionSlop = opts.correctionSlop ?? 0.01;
  }

  add(body: Body): Body {
    this.bodies.push(body);
    return body;
  }

  remove(body: Body): boolean {
    const i = this.bodies.indexOf(body);
    if (i < 0) return false;
    this.bodies.splice(i, 1);
    return true;
  }

  findContacts(): Contact[] {
    const contacts: Contact[] = [];
    for (let i = 0; i < this.bodies.length; i++) {
      for (let j = i + 1; j < this.bodies.length; j++) {
        const c = collide(this.bodies[i], this.bodies[j]);
        if (c) contacts.push(c);
      }
    }
    return contacts;
  }

  step(dt: number): void {
    // 1) Integrate external forces into velocities (semi-implicit Euler).
    for (const b of this.bodies) {
      if (b.isStatic) continue;
      b.velocity.x += (this.gravity.x + b.force.x * b.invMass) * dt;
      b.velocity.y += (this.gravity.y + b.force.y * b.invMass) * dt;
    }

    // 2) Detect contacts at current positions.
    const contacts = this.findContacts();
    this.lastContacts = contacts;

    // 3) Solve velocity constraints (sequential impulses).
    solveContacts(contacts, this.iterations);

    // 4) Baumgarte-style positional correction to remove sinking.
    for (const c of contacts) {
      correctPositions(c, this.correctionPercent, this.correctionSlop);
    }

    // 5) Integrate positions.
    for (const b of this.bodies) {
      if (b.isStatic) continue;
      b.position.x += b.velocity.x * dt;
      b.position.y += b.velocity.y * dt;
    }
  }
}
"})
