 * solver.ts — contact generation and the sequential impulse solver with
 * accumulated-impulse clamping, plus Baumgarte-style positional correction.
 */

import { type Body, type Vec2 } from './body';

export interface Contact {
  a: Body;
  b: Body;
  /** Unit contact normal pointing from `a` towards `b`. */
  normal: Vec2;
  /** Overlap depth along the minimum-penetration axis. */
  penetration: number;
}

/** Narrowphase: AABB vs AABB. Returns null when disjoint. */
export function collide(a: Body, b: Body): Contact | null {
  const dx = b.position.x - a.position.x;
  const dy = b.position.y - a.position.y;

  const overlapX = a.halfExtent.x + b.halfExtent.x - Math.abs(dx);
  if (overlapX <= 0) return null;
  const overlapY = a.halfExtent.y + b.halfExtent.y - Math.abs(dy);
  if (overlapY <= 0) return null;

  // Minimum penetration axis. On exact ties prefer the axis with actual
  // relative displacement so resting stacks resolve vertically.
  if (overlapY < overlapX || (overlapY === overlapX && dy !== 0)) {
    const ny = dy > 0 ? 1 : -1;
    return { a, b, normal: { x: 0, y: ny }, penetration: overlapY };
  }
  const nx = dx > 0 ? 1 : -1;
  return { a, b, normal: { x: nx, y: 0 }, penetration: overlapX };
}

interface ContactSolver {
  a: Body;
  b: Body;
  nx: number;
  ny: number;
  tx: number;
  ty: number;
  penetration: number;
  /** Effective mass along the normal (1 / (invMassA + invMassB)). */
  massNormal: number;
  massTangent: number;
  /** Accumulated normal impulse (>= 0). */
  accNormalImpulse: number;
  /** Accumulated tangent impulse, |accTangent| <= mu * accNormal. */
  accTangentImpulse: number;
  restitution: number;
  friction: number;
  /** Target normal velocity to reach: bias for restitution. */
  targetVn: number;
}

function prepare(contact: Contact): ContactSolver {
  const { a, b } = contact;
  const invMassSum = a.invMass + b.invMass;
  const nx = contact.normal.x;
  const ny = contact.normal.y;
  // Tangent is the normal rotated 90°.
  const tx = -ny;
  const ty = nx;

  // Restitution only when bodies are approaching meaningfully; zero for
  // near-resting contacts so stacks settle instead of micro-bouncing.
  const rvx = b.velocity.x - a.velocity.x;
  const rvy = b.velocity.y - a.velocity.y;
  const vn = rvx * nx + rvy * ny;
  const e = vn < -1 ? Math.min(a.restitution, b.restitution) : 0;

  return {
    a,
    b,
    nx,
    ny,
    tx,
    ty,
    penetration: contact.penetration,
    massNormal: invMassSum > 0 ? 1 / invMassSum : 0,
    massTangent: invMassSum > 0 ? 1 / invMassSum : 0,
    accNormalImpulse: 0,
    accTangentImpulse: 0,
    restitution: e,
    friction: Math.sqrt(a.friction * b.friction),
    targetVn: -e * vn,
  };
}

function applyImpulse(s: ContactSolver, jx: number, jy: number): void {
  s.a.velocity.x -= jx * s.a.invMass;
  s.a.velocity.y -= jy * s.a.invMass;
  s.b.velocity.x += jx * s.b.invMass;
  s.b.velocity.y += jy * s.b.invMass;
}

function solveOne(s: ContactSolver): void {
  const rvx = s.b.velocity.x - s.a.velocity.x;
  const rvy = s.b.velocity.y - s.a.velocity.y;

  // --- Normal impulse, clamped to be non-negative (accumulated) ---
  const vn = rvx * s.nx + rvy * s.ny;
  let lambda = -vn * s.massNormal;
  const newAccN = Math.max(s.accNormalImpulse + lambda, 0);
  lambda = newAccN - s.accNormalImpulse;
  s.accNormalImpulse = newAccN;
  applyImpulse(s, lambda * s.nx, lambda * s.ny);

  // --- Friction impulse, clamped to the Coulomb cone (accumulated) ---
  const rvx2 = s.b.velocity.x - s.a.velocity.x;
  const rvy2 = s.b.velocity.y - s.a.velocity.y;
  const vt = rvx2 * s.tx + rvy2 * s.ty;
  let lt = -vt * s.massTangent;
  const maxFriction = s.friction * s.accNormalImpulse;
  const newAccT = Math.min(Math.max(s.accTangentImpulse + lt, -maxFriction), maxFriction);
  lt = newAccT - s.accTangentImpulse;
  s.accTangentImpulse = newAccT;
  applyImpulse(s, lt * s.tx, lt * s.ty);
}

/** Run `iterations` sweeps of sequential impulses over the contact list. */
export function solveContacts(contacts: Contact[], iterations: number): void {
  if (contacts.length === 0) return;
  const solvers = contacts.map(prepare);
  for (let it = 0; it < iterations; it++) {
    for (const s of solvers) solveOne(s);
  }
}

/**
 * Baumgarte-style positional correction: push the bodies apart along the
 * contact normal by `percent` of the penetration beyond `slop`, split
 * proportionally to inverse mass. Applied once per step after velocity
 * solving, so it removes sinking without injecting solver energy.
 */
export function correctPositions(
  contact: Contact,
  percent: number,
  slop: number,
): void {
  const { a, b, normal, penetration } = contact;
  const invMassSum = a.invMass + b.invMass;
  if (invMassSum <= 0) return;

  const magnitude = (Math.max(penetration - slop, 0) * percent) / invMassSum;
  if (magnitude === 0) return;

  a.position.x -= normal.x * magnitude * a.invMass;
  a.position.y -= normal.y * magnitude * a.invMass;
  b.position.x += normal.x * magnitude * b.invMass;
  b.position.y += normal.y * magnitude * b.invMass;
}
